() => {
  const el = document.querySelector('[aria-label="Incident report content"]') || document.activeElement;
  function describe(node) {
    if (!node) return null;
    return {
      tag: node.tagName,
      role: node.getAttribute && node.getAttribute('role'),
      contentEditable: node.contentEditable,
      className: node.className,
      isTextarea: node.tagName === 'TEXTAREA',
    };
  }
  const region = document.querySelector('[aria-label="Document editor"]') || document.querySelector('region');
  let found = document.querySelector('[role="textbox"]');
  return {
    found: describe(found),
    outerHTMLSnippet: found ? found.outerHTML.slice(0, 500) : null,
  };
}

